SELECT MAX(`Free Meal Count (K-12)` * 1.0 / `Enrollment (K-12)`) AS highest_eligible_free_rate
FROM frpm
WHERE `County Name` = 'Alameda';

SELECT AdmFName1 || ' ' || AdmLName1, AdmFName2 || ' ' || AdmLName2, AdmFName3 || ' ' || AdmLName3
FROM schools
WHERE CDSCode = (SELECT cds FROM satscores ORDER BY NumGE1500 DESC LIMIT 1);

SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT DisplayName
FROM users
WHERE Reputation = (SELECT MAX(Reputation) FROM users);

SELECT DisplayName
FROM users
WHERE Age BETWEEN 19 AND 65;

SELECT COUNT(*) 
FROM comments 
WHERE PostId = (SELECT Id FROM posts WHERE Score = (SELECT MAX(Score) FROM posts));

SELECT SUM(CASE WHEN Currency = 'EUR' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) 
FROM customers 
WHERE Segment = 'KAM';

SELECT SUM(CASE WHEN Consumption > 528.3 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage
FROM yearmonth
WHERE Date = '201202';

SELECT SUM(CASE WHEN Segment = 'Premium' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS premium_percentage
FROM gasstations
WHERE Country = 'SVK';

SELECT CAST(SUM(CASE WHEN Segment = 'Premium' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)
FROM gasstations
WHERE Country = 'SVK';
